import{R as t,e as o,f as a,U as i}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"theming/overview.md","filePath":"theming/overview.md","lastUpdated":1775985606000}'),r={name:"theming/overview.md"};function n(s,e,l,h,u,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>While Formie aims to make rendering forms simple, it is just as important to be able to customize that output so it fits the rest of your site.</p><p>Formie gives you a few different ways to do that. Start with the lightest option that gives you enough control.</p><h2 id="theme-config" tabindex="-1">Theme Config <a class="header-anchor" href="#theme-config" aria-label="Permalink to &quot;Theme Config&quot;">​</a></h2><p>Theme config is usually the best place to start, and for most projects it is enough.</p><p>It lets you define the HTML tags and attributes used for parts of the form and its fields. That means you can add or remove classes, add data attributes, change wrappers, or even remove some elements entirely.</p><p>This works especially well when you want forms to fit a front-end system like Tailwind or Bootstrap, because you can control the HTML attributes directly without having to override Twig templates.</p><h3 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h3><ul><li>you want to add Tailwind or Bootstrap classes</li><li>you want to remove or replace Formie&#39;s default classes</li><li>you want to adjust HTML attributes or wrappers without rewriting templates</li><li>you want to keep maintenance lower as Formie evolves</li></ul><h3 id="when-not-to-use-it" tabindex="-1">When not to use it <a class="header-anchor" href="#when-not-to-use-it" aria-label="Permalink to &quot;When not to use it&quot;">​</a></h3><ul><li>you want full control over every template</li><li>you prefer to work directly in Twig templates</li></ul><p>Read more in <a href="/theming/theme-config">Theme Config</a>.</p><h2 id="template-overrides" tabindex="-1">Template Overrides <a class="header-anchor" href="#template-overrides" aria-label="Permalink to &quot;Template Overrides&quot;">​</a></h2><p>Template overrides are the next step when theme config is not enough.</p><p>They let you override individual Twig templates for forms, fields, buttons, labels, alerts, and other parts of the rendered output. The main advantage is that this does not have to be all-or-nothing. You can override just the parts you need and leave the rest using Formie&#39;s defaults.</p><h3 id="when-to-use-it-1" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it-1" aria-label="Permalink to &quot;When to use it&quot;">​</a></h3><ul><li>you want to customize one part of the form, such as the buttons or a field template</li><li>you want more control than theme config provides</li><li>you are comfortable maintaining Twig overrides over time</li></ul><h3 id="when-not-to-use-it-1" tabindex="-1">When not to use it <a class="header-anchor" href="#when-not-to-use-it-1" aria-label="Permalink to &quot;When not to use it&quot;">​</a></h3><ul><li>you only need to add or remove classes or attributes</li><li>you do not want the maintenance that comes with template overrides</li><li>you want to take over the entire rendering process yourself</li></ul><p>Read more in <a href="/theming/template-overrides">Template Overrides</a>.</p><h2 id="custom-rendering" tabindex="-1">Custom Rendering <a class="header-anchor" href="#custom-rendering" aria-label="Permalink to &quot;Custom Rendering&quot;">​</a></h2><p>Custom rendering is the most involved approach. Instead of letting Formie render the form for you, you take responsibility for rendering the form, pages, and fields yourself.</p><p>This gives you the most control, but it also means you take on the most maintenance. As Formie changes, your custom templates may need to change with it. In most cases, this should be the last option you reach for, not the first.</p><h3 id="when-to-use-it-2" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it-2" aria-label="Permalink to &quot;When to use it&quot;">​</a></h3><ul><li>you have a very specific or unusual rendering requirement</li><li>you are building a highly custom front end</li><li>you want complete control over the markup</li></ul><h3 id="when-not-to-use-it-2" tabindex="-1">When not to use it <a class="header-anchor" href="#when-not-to-use-it-2" aria-label="Permalink to &quot;When not to use it&quot;">​</a></h3><ul><li>you only need to tweak one or two parts of the form</li><li>theme config or template overrides would already solve the problem</li><li>you do not want to maintain custom rendering over time</li></ul><p>Read more in <a href="/theming/custom-rendering">Custom Rendering</a>.</p>',28)])])}const c=t(r,[["render",n]]);export{p as __pageData,c as default};
